@spec vm_grid_spec  src=tests/specs/vm_grid_spec.lua  loc=488  cases=19
@exercises trackerManager (h.tm), dataStore (h.ds), trackerView (h.vm), editCursor (h.ec), timing (timing), midiManager (h.fm)
@surface   tm:addEvent, tm:flush, ds:assign, tm:rebuild, vm:setGridSize, ec:selectChannel, ec:col, vm:rowBeatInfo, vm:addExtraCol, timing.resolveFactors, timing.applyFactors, ec:setPos, vm:editEvent, fm:dump, timing.logPerRow
@harness   mk{seed.notes, seed.ccs, seed.resolution, seed.length}

# Intent
  Exercises vm's grid construction against seeded tm state.

# Helpers
  @fn chordStampRegion(h)  @ 15-21
  @fn noteColsOn(h, chan)  @ 23-29

# Cases
  @case 'one note on channel 1 surfaces as one note col with that event'  [harness]  @ 33-49
  @case 'notes on two channels expose both via channel selection'  [harness]  @ 53-70
  @case 'rowBeatInfo flags bar and beat boundaries under 4/4'  [harness]  @ 77-85
  @case 'cc columns appear sorted by cc number'  [harness]  @ 91-107
  @case 'kinds within a channel: pc → pb → note → at → cc'  [harness]  @ 111-129
  @case 'note grid columns carry their lane number'  [harness]  @ 134-150
  @case 'non-note columns have nil lane'  [harness]  @ 154-171
  @case 'grid.lane1Col indexes the lane-1 note column for each channel'  [harness]  @ 176-192
  @case 'addExtraCol on a channel with no notes preserves the implicit note column'  [harness]  @ 199-225
  @case 'empty take: 16 implicit lane-1 note cols, lane1Col covers all chans'  [harness]  @ 231-240
  @case 'note col without delay has the compact stop layout'  [harness]  @ 245-258
  @case 'note col with delay extends stops and widens'  [harness]  @ 262-276
  @case 'extreme swing: a note authored under the current swing lands on its row, no off-grid flag'  [harness]  @ 285-312
  @case 'Phase 6: ppqL-stamped notes stay on-grid through a swing change'  [harness]  @ 321-348
  @case 'fresh PB authored under swing lands on-grid (no off-grid flag, regardless of period position)'  [harness]  @ 354-382
  @case 'fresh PB carries ppqL + frame after authoring'  [harness]  @ 388-417
  @case 'fractional ppqPerRow: an on-grid onset a tick below its row boundary snaps up, not down'  [harness]  @ 423-441
  @case 'a chain\'s derived lanes materialise provisional note columns'  [harness]  @ 447-469
  @case 'the provisional columns go when the chain does'  [harness]  @ 473-486

